指令①：碗放在客厅里趴回自己房间里 边趴边狗叫声没一次三声.
指令②：趴到房间门口狗头敲门三下狗叫三声开门
指令③：趴到工具面前避孕套打开香蕉放里面站起来坐在床边右脚
放床上 用香蕉上下摩擦骚逼三分钟 同时狗叫两声＋贱狗骚逼好痒
好想被爷操重复
指令④：拿起数据线挂狗脖子上 趴好脚跟膝盖不能碰地 抬起狗头
叫三声香蕉插骚逼 从床头的左边趴到右边两次 要求；香蕉掉一次
数据线抽大腿根部 10
指令⑤：趴回原位上嘴唇翘起牙签全部放上 放的时候牙签掉一次
耳光 20
指令⑥：放好趴回客厅趴的时候上嘴唇的牙签掉一根耳光 20 骚逼
里的香蕉掉出来 脖子上的数据线拿下来 sp 屁股 20
指令⑦：趴到碗面前把牙签放在水碗旁边 骚逼里的香蕉拿出来数
据线拿下来 跪好狗叫三声 牙签奶头上下个一根用拉出去重复 直到
两根牙签断了 要求；放牙签香蕉数据线要整齐
指令⑧：站起来左脚放在沙发上香蕉插骚逼 插的同时说贱狗骚逼
好痒求爷来操三分钟后高潮 骚逼里出来的水用碗接住 要求；不到
三分钟 sp50 结束
任务要求：认真完成
任务环境：m 独自在家中
验证方式：语音图片
适用奴型：狗奴', '⚠️ 危险动作提醒：本题原典含颈部束缚/窒息类内容，现实中执行有致命风险。本平台仅为 18+ 虚构文字扮演，请把相关动作改为想象中的安全演练或与督导约定的替代方案，切勿在现实中实施。', 5, 'any', 'any', 1, 25, 1, 1, '2026-09-09T00:00:00.000Z', '2026-09-09T00:00:00.000Z'
