任务工具：皮带 1 根，绳子 1 根，温水若干，筷子 3 双，皮筋四
指令 2、用嘴咬着皮带一头，着内衣在屋内爬行 3 圈，每爬 3 步，
扭动 3 下屁股，狗叫 2 声。墙角狗食盆（或洗菜盆），里面温开
水若干，每次经过舔 6 下，说谢谢渔翁爷(舔水要有声,说话语音汇
报、上图)。
指令 3、执行完第二步后，喝下 1000-1500 毫升温开水，脱去内
裤，用麻绳自做绳裤穿上(上图验证)。
指令 4、穿上裙子（内空式，即不穿罩罩、只有绳裤），去附近菜
市场买菜，拿在手里(蹲下结账时上图验证)，结帐回家。
指令 5、回家之后，全裸上身，跪在 3 双筷子上。4 根皮筋连在一
起，左右都绑在奶头上，起到拉扯奶头的作用(上图验证)。拉皮筋
40 下，然后取下，用指甲刮奶头，各 30(发语音)，直至狗逼流
水。
指令 6、爬在地下，额头着地，屁股上翘，左手母按压阴蒂上方阴
毛处（耻骨连合膀胱处），食指揉阴蒂 1 分钟，若尿意不强继续
玩弄狗奶头、阴蒂。3-4 分钟后，尿意强烈，憋住，按揉小腹一分
半钟，尿坚持不住时，脱下绳裤，站镜子前，前面放菜盆，说 5
遍“我是纯高的贱狗”，跪下求爷，直至临畀点，在镜子前面，自
己看着自已，单腿抬起，狗姿式，尿在菜盆中，分 4 次尿完，每
次 3-5 秒钟。
任务要求：认真执行注意安全
验证方式：图片语音视频（方便自选）
适用奴型：狗奴', '', 5, 'any', 'any', 1, 25, 1, 31, '2026-09-09T00:00:00.000Z', '2026-09-09T00:00:00.000Z'
FROM task_packs WHERE name = 'K9 犬训 · 原典 200 题';
