指令①：跪姿，眼罩戴上（无眼罩可替换其他遮挡物品）房内门至
窗来回爬行 5 圈并。仔细聆听周围动静（2 分钟完成，正负 5 秒算
合格。未达成则相差秒数 x10 罚 sp）
指令②：耳朵塞上棉球，叼住一纸杯小狗欢快状原地转圈 10 次
39 秒完成，请求玩耍指令后抛出纸杯。时间不达标 x8 罚抽大腿两
内侧。
