求奖励。（奖励双手揉捏臀部 1 分钟）（如未完成数据线对折抽
后背 60 全力）
指令④：牙齿咬住另一纸杯（事前装半杯水）边缘开始沿墙爬行至
门口，如纸杯水泼出罚左右各 50sp，如完成奖励保持动作喝完杯
中水。
指令⑤：用嘴吸力吸住纸杯保持不掉落，计时 33 秒。如 m 时间
不达标罚相差秒数 x10 全力数据线抽后背。
指令⑥：跪趴姿势，纸杯放于头顶 47 秒后 5 秒内完成由跪趴到站
立。如纸杯掉落罚 50 数据线，顶杯时间差，秒数 x10 罚两侧 sp
程监督
任务要求：室内，环境安静，注意家具磕碰。任务分解必须手表全
验证方式：语音
适用奴型：K9，轻刑', '', 5, 'any', 'any', 1, 25, 1, 81, '2026-09-09T00:00:00.000Z', '2026-09-09T00:00:00.000Z'
