个。用力听响度。没高潮换边，重复。直到高潮。
指令⑧：高潮后，黄瓜顶到最深。掰断。就在骚逼里。穿好内裤、
丝袜。写 100 字玩弄感受。语音朗读。发语音条到群里。经 5 位 s
同意后才可以取出来。每有 1 位不同意，5 位变 6 位，7 位，依次
继续。
